exercises.solution:
def is_balanced(text):
    stack = []
    for ch in text:
        if ch == "(":
            stack.append(ch)
        elif ch == ")":
            if not stack:
                return False
            stack.pop()
    return not stack

def serve(queue, n):
    served = []
    while queue and len(served) < n:
        served.append(queue.pop(0))
    return served

